def validate_topics():
    print(f"Validating AMC topics: count = {len(AMC_TOPICS)}")
    assert len(AMC_TOPICS) == 100, f"Expected 100 AMC topics, got {len(AMC_TOPICS)}"
    for idx, item in enumerate(AMC_TOPICS):
        title, subj, sys, hallmark, ref_lbl, ref_url = item
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at AMC #{idx+1}: {title}"
        assert sys in TAXONOMY_SYSTEMS, f"Invalid system {sys} at AMC #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short at AMC #{idx+1}"
        assert len(hallmark) >= 15, f"Hallmark too short at AMC #{idx+1}"
        assert ref_url.startswith("https://"), f"Invalid ref_url at AMC #{idx+1}"
    print("  -> All 100 AMC topics PASSED validation!")

    print(f"Validating MCCQE topics: count = {len(MCCQE_TOPICS)}")
    assert len(MCCQE_TOPICS) == 100, f"Expected 100 MCCQE topics, got {len(MCCQE_TOPICS)}"
    for idx, item in enumerate(MCCQE_TOPICS):
        title, subj, sys, hallmark, ref_lbl, ref_url = item
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at MCCQE #{idx+1}: {title}"
        assert sys in TAXONOMY_SYSTEMS, f"Invalid system {sys} at MCCQE #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short at MCCQE #{idx+1}"
        assert len(hallmark) >= 15, f"Hallmark too short at MCCQE #{idx+1}"
        assert ref_url.startswith("https://"), f"Invalid ref_url at MCCQE #{idx+1}"
    print("  -> All 100 MCCQE topics PASSED validation!")

    print(f"Validating NEET_PG topics: count = {len(NEET_PG_TOPICS)}")
    assert len(NEET_PG_TOPICS) == 100, f"Expected 100 NEET_PG topics, got {len(NEET_PG_TOPICS)}"
    for idx, item in enumerate(NEET_PG_TOPICS):
        title, subj, sys, hallmark, ref_lbl, ref_url = item
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at NEET_PG #{idx+1}: {title}"
        assert sys in TAXONOMY_SYSTEMS, f"Invalid system {sys} at NEET_PG #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short at NEET_PG #{idx+1}"
        assert len(hallmark) >= 15, f"Hallmark too short at NEET_PG #{idx+1}"
        assert ref_url.startswith("https://"), f"Invalid ref_url at NEET_PG #{idx+1}"
    print("  -> All 100 NEET_PG topics PASSED validation!")

def export_topics():
    out_file = os.path.join(os.path.dirname(__file__), "mega90_topics_b.py")
    with open(out_file, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 90 Part B topics (AMC 100, MCCQE 100, NEET_PG 100)\n\n")
        f.write("AMC_TOPICS = " + json.dumps(AMC_TOPICS, indent=2) + "\n\n")
        f.write("MCCQE_TOPICS = " + json.dumps(MCCQE_TOPICS, indent=2) + "\n\n")
        f.write("NEET_PG_TOPICS = " + json.dumps(NEET_PG_TOPICS, indent=2) + "\n")
    print(f"Successfully generated {out_file} with 300 topics!")

if __name__ == "__main__":
    validate_topics()
    export_topics()
